// Hand-written `sequelize-typescript` stub for the flowatlas fixture suite. It declares
// only what `fixtures/nest-sequelize-typescript/src` touches, shaped like the real
// library: a `Model` base that extends sequelize's own, a `@Table` decorator that states
// the table, and a `scope` that retypes the model to sequelize's `ModelStatic`.
//
// This is the shape the fixture exists for. The model class is declared in the
// repository and the base chain reaches a package, so the origin of a call on it is
// `sequelize-typescript` — which is not the package the descriptor is written for. The
// descriptor is `sequelize`'s, and every word of it is right for this library, so the two
// names are one library and the alias record says so.

import { Model as SequelizeModel } from 'sequelize';

export declare class Model<Attributes = unknown, Creation = unknown> extends SequelizeModel {}

export declare function Table(options: Record<string, unknown>): ClassDecorator;
export declare function Column(options?: Record<string, unknown>): PropertyDecorator;
export declare function Scopes(scopes: Record<string, unknown>): ClassDecorator;
